CREATE TABLE fb_segment_browse
(
    id              BIGINT       NOT NULL auto_increment COMMENT 'id',
    unique_key 		VARCHAR(64)  NOT NULL COMMENT '唯一值(一般是Id)',
    parent_key      VARCHAR(64)  NOT NULL COMMENT '父唯一值(一般是Id)',
    name            VARCHAR(128)  NOT NULL COMMENT '名称',
    type            VARCHAR(32)  DEFAULT NULL COMMENT '类别',
    path 			VARCHAR(512) DEFAULT NULL COMMENT '层级路径',
    description     VARCHAR(128) DEFAULT NULL COMMENT '描述',
    audience_size_lower_bound INTEGER DEFAULT NULL COMMENT '目标受众规模的预估值下限',
    audience_size_upper_bound INTEGER DEFAULT NULL COMMENT '目标受众规模的预估值上限',
    created         datetime     DEFAULT CURRENT_TIMESTAMP,
    updated         datetime     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
) ENGINE = INNODB COMMENT = '细分浏览数据表';


